import json, pathlib
for name in ['source.json','policy.json','coordination.json']:
 p=pathlib.Path(name); x=json.loads(p.read_text()); print(name,'bytes',p.stat().st_size,'type',type(x).__name__)
 if isinstance(x,dict):
  for k,v in x.items(): print(' ',k, type(v).__name__,len(v) if hasattr(v,'__len__') else '')
 elif isinstance(x,list):
  for i,v in enumerate(x): print(i, {k:(len(z) if isinstance(z,(str,list,dict)) else z) for k,z in v.items()})
